// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 numCalls) public {
        vm.assume(numCalls >= 1);
        vm.assume(numCalls <= 10);
        address player = makeAddr("player");
        vm.deal(player, 10 ether);
        vm.startPrank(player);
        for(uint256 i = 0; i < numCalls; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();
        assertTrue(c.pot() >= numCalls * 10);
    }
}
